SELECT t_sys_menu.id,
arr.pid
t_sys_menu.pid
AS pid, t_sys_menu.name, t_sys_menu.path, t_sys_menu.component, t_sys_menu.redirect, t_sys_menu.wrappers, t_sys_menu.icon, t_sys_menu.create_time AS createTime, t_sys_menu.update_time AS updateTime, t_sys_menu.menu_config AS menuConfig, t_sys_menu.hide_in_menu AS hideInMenu, t_sys_menu.perm_id AS permId, t_sys_menu.order_num AS orderNum, t_sys_menu.menu_type AS menuType, t_sys_menu.is_frame AS isFrame, t_sys_menu.is_cache AS isCache, t_sys_menu.visible, t_sys_menu.status, t_sys_menu.page_id AS pageId, t_sys_menu.delete_flag AS deleteFlag FROM t_sys_menu
INNER JOIN t_app_res_relation arr ON t_sys_menu.id = arr.res_id AND arr.res_type = 'menu' AND arr.app_id = #{appId}
arr.pid IN
t_sys_menu.pid IN
#{index}
and t_sys_menu.status = #{status}
ORDER BY t_sys_menu.order_num ASC

